from pathlib import Path
import sys,json,copy,numpy as np,importlib.util
p=Path(__file__).resolve().parent;parent=p.parent/'rain-reference-wave-fidelity';sys.path.insert(0,str(p.parent/'rain-coupled-reference'))
import model as m
from wave import wave,ops
spec=importlib.util.spec_from_file_location('state_compare','experiments/gpu-physics/scripts/compare-core-state.py');compare=importlib.util.module_from_spec(spec);spec.loader.exec_module(compare)
a=json.loads((parent/'hip-probe/trace.jsonl').read_text());b=json.loads((p/'hip-probe/trace.jsonl').read_text());fields=['frame_a_rotation','frame_b_rotation','target_rotation','weld_angular_impulse','perp_impulse','impulse','spring_impulse','motor_impulse']
def stripped(d):
 d=copy.deepcopy(d)
 for j in d['joints']:
  if j['kind']==5:
   for field in fields:j.pop(field)
 return d
raw_diff=compare.difference(stripped(a),stripped(b));diff=compare.difference(compare.audited_storage_view(stripped(a)),compare.audited_storage_view(stripped(b)));assert diff is None,diff
assert (parent/'hip-probe/state.txt').read_bytes()==(p/'hip-probe/state.txt').read_bytes()
corrupt=copy.deepcopy(b);corrupt['bodies'][1]['vel'][0]='3f800000';assert compare.difference(compare.audited_storage_view(stripped(a)),compare.audited_storage_view(stripped(corrupt)))
values=[]
for j in b['joints']:
 if j['kind']==5:
  for field in fields:
   value=j[field];values.extend(m.v(value) if isinstance(value,list) else [m.f(value)])
assert len(values)==60
contacts={json.dumps(c['identity']):c for c in a['contacts']};normal_blocks={json.dumps(block['label'][1])+':'+str(block['label'][3]):block for block in m.blocks if block['label'][0]=='contact' and block['label'][2]=='normal'}
records=[];index=0
for identities in a['contact_color_order']:
 for identity in identities:
  c=contacts[json.dumps(identity)];assert c['chain_length']<=1 and c['identity'][1]==0
  for k in range(c['count']):
   block=normal_blocks[json.dumps(identity)+':'+str(k)];sep=float(values[index]);new=max(0,sep)/m.h;records.append(dict(identity=identity,point=k,exact_separation=sep,previous_bias=float(block['bias'][0]),exact_bias=new));block['bias'][:]=new;index+=1
assert index==m.normal_count==56
m.bias=np.concatenate([block['bias'] for block in m.blocks]);m.g=m.J@m.vfree+m.bias
for op in ops:op['bias']=m.bias[op['indices']]
state=np.load(parent/'comparison.npz');x,stats=wave(m.old);v=m.vfree+m.M@m.J.T@x;rel=lambda a,b:abs(a-b)/(1+np.maximum(abs(a),abs(b)));ie=rel(x,state['actual_impulses']);ve=rel(v,state['actual_velocity']);passed=max(max(ie),max(ve))<=2e-5
ranked=sorted([dict(label=block['label'],relative_error=float(max(ie[block['sl']]))) for block in m.blocks],key=lambda x:x['relative_error'],reverse=True)
old_root=np.load(m.p/'polished-solution.npz')['impulses'];old_root_error=float(np.max(abs(m.residual(old_root))/(1+abs(old_root))))
result=dict(original_endpoint_root_residual_with_exact_bias=old_root_error,status='corrected-fidelity-pass' if passed else 'corrected-fidelity-failed',body_stream_exact=True,complete_state_difference_excluding_declared_fields=diff,raw_difference_excluding_fields=raw_diff,corruption_rejected=True,points_captured=index,maximum_relative_impulse_error=float(max(ie)),maximum_relative_velocity_error=float(max(ve)),worst_velocity_body=int(np.argmax(ve)//6+1),predicted_wave=stats,ranked_blocks=ranked,separations=records,scope='Exact pre-wave separations replace rounded endpoint reconstruction; one next-wave fidelity check only, not original phase-entry or trajectory qualification.')
(p/'result.json').write_text(json.dumps(result,indent=2));np.savez(p/'corrected-comparison.npz',predicted_impulses=x,predicted_velocity=v,bias=m.bias)
print(json.dumps({k:v for k,v in result.items() if k not in ['ranked_blocks','separations']},indent=2));print(json.dumps(ranked[:5],indent=2))
if not passed:raise SystemExit(1)

